// Central config: list of Indian banks to monitor and their per-source query hints.
// Edit this node to add/remove banks without touching downstream logic.
const banks = [
  {
    bank_name: 'HDFC Bank',
    place_query: 'HDFC Bank branch India',
    twitter_query: '("HDFC Bank" OR "@HDFC_Bank") -is:retweet lang:en',
    scraper_slug: 'hdfc-bank'
  },
  {
    bank_name: 'ICICI Bank',
    place_query: 'ICICI Bank branch India',
    twitter_query: '("ICICI Bank" OR "@ICICIBank") -is:retweet lang:en',
    scraper_slug: 'icici-bank'
  },
  {
    bank_name: 'State Bank of India',
    place_query: 'State Bank of India branch',
    twitter_query: '("SBI" OR "State Bank of India" OR "@TheOfficialSBI") -is:retweet lang:en',
    scraper_slug: 'sbi'
  },
  {
    bank_name: 'Axis Bank',
    place_query: 'Axis Bank branch India',
    twitter_query: '("Axis Bank" OR "@AxisBank") -is:retweet lang:en',
    scraper_slug: 'axis-bank'
  },
  {
    bank_name: 'Kotak Mahindra Bank',
    place_query: 'Kotak Mahindra Bank branch India',
    twitter_query: '("Kotak" OR "@KotakBankLtd") -is:retweet lang:en',
    scraper_slug: 'kotak-mahindra-bank'
  }
];

const runId = $jmespath({ _: 'x' }, '_') ? '' : '';
// Generate a deterministic run_id per execution for audit correlation
const crypto = require('crypto');
const run_id = crypto.randomUUID();
const run_started_at = new Date().toISOString();

return banks.map(b => ({
  json: {
    ...b,
    run_id,
    run_started_at,
    lookback_hours: 24
  }
}));

// Flatten the places[] array into one item per branch, carry bank context forward.
const out = [];
for (const item of $input.all()) {
  const bank = item.json.bank_name || $('Banks Config').item.json.bank_name;
  const run_id = item.json.run_id || $('Banks Config').item.json.run_id;
  const places = (item.json.places || []);
  for (const p of places) {
    out.push({
      json: {
        bank_name: bank,
        run_id,
        place_id: p.id,
        branch: (p.displayName && p.displayName.text) || null,
        address: p.formattedAddress || null,
        place_rating: p.rating || null
      }
    });
  }
}
return out;

// Map Google Place reviews -> raw intermediate schema.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const reviews = j.reviews || [];
  const branchName = (j.displayName && j.displayName.text) || item.json.branch || null;
  const placeUri = j.googleMapsUri || null;
  for (const r of reviews) {
    out.push({
      json: {
        bank_name: item.json.bank_name,
        run_id: item.json.run_id,
        branch: branchName,
        rating: typeof r.rating === 'number' ? r.rating : null,
        feedback_text: (r.originalText && r.originalText.text) || (r.text && r.text.text) || '',
        author: (r.authorAttribution && r.authorAttribution.displayName) || null,
        review_date: r.publishTime || null,
        source: 'Google Maps',
        source_url: (r.authorAttribution && r.authorAttribution.uri) || placeUri
      }
    });
  }
}
return out;

// Join tweets with user expansions and map to raw schema.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const tweets = j.data || [];
  const users = ((j.includes && j.includes.users) || []).reduce((m, u) => { m[u.id] = u; return m; }, {});
  const bank_name = $('Banks Config').item.json.bank_name;
  const run_id = $('Banks Config').item.json.run_id;
  for (const t of tweets) {
    const u = users[t.author_id] || {};
    out.push({
      json: {
        bank_name,
        run_id,
        branch: null,
        rating: null,
        feedback_text: t.text || '',
        author: u.username ? '@' + u.username : null,
        review_date: t.created_at || null,
        source: 'Twitter',
        source_url: u.username ? `https://twitter.com/${u.username}/status/${t.id}` : null
      }
    });
  }
}
return out;

// Accept scraper payloads shaped as { reviews: [ {review_text, rating, author, date, url, source_name} ] }
// or as a raw array of the same objects.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const bank_name = $('Banks Config').item.json.bank_name;
  const run_id = $('Banks Config').item.json.run_id;
  const arr = Array.isArray(j) ? j : (j.reviews || []);
  for (const r of arr) {
    out.push({
      json: {
        bank_name,
        run_id,
        branch: r.branch || null,
        rating: r.rating != null ? Number(r.rating) : null,
        feedback_text: r.review_text || r.text || '',
        author: r.author || null,
        review_date: r.date || r.review_date || null,
        source: r.source_name || 'Scraper',
        source_url: r.url || null
      }
    });
  }
}
return out;

// Unified normalization + defensive cleanup.
// Drops rows with empty feedback_text, normalizes review_date to ISO UTC.
const { DateTime } = require('luxon');

function toIsoUtc(v) {
  if (!v) return null;
  try {
    const dt = DateTime.fromISO(String(v), { zone: 'utc' });
    if (dt.isValid) return dt.toUTC().toISO();
    const jsd = new Date(v);
    return isNaN(jsd.getTime()) ? null : jsd.toISOString();
  } catch (_) {
    return null;
  }
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const text = String(j.feedback_text || '').trim();
  if (!text) continue; // skip empty
  out.push({
    json: {
      run_id: j.run_id || null,
      bank_name: String(j.bank_name || '').trim(),
      branch: j.branch ? String(j.branch).trim() : null,
      rating: j.rating != null && !isNaN(Number(j.rating)) ? Number(j.rating) : null,
      feedback_text: text.slice(0, 8000), // cap payload
      author: j.author ? String(j.author).trim().slice(0, 200) : null,
      review_date: toIsoUtc(j.review_date) || new Date().toISOString(),
      source: String(j.source || 'Unknown'),
      source_url: j.source_url || null
    }
  });
}
return out;

// Deterministic SHA256 dedup hash = sha256(source + feedback_text + review_date)
const crypto = require('crypto');
return $input.all().map(item => {
  const j = item.json;
  const h = crypto.createHash('sha256')
    .update(String(j.source) + String(j.feedback_text) + String(j.review_date))
    .digest('hex');
  return { json: { ...j, hash: h } };
});

// Postgres node is 1:1 with inputs but returns 0 rows on miss.
// Merge dedup answer back with the original record by position.
const inputRecords = $('Add SHA256 Hash').all();
const dbRows = $input.all();
const out = [];
for (let i = 0; i < inputRecords.length; i++) {
  const rec = inputRecords[i].json;
  const row = dbRows[i] && dbRows[i].json;
  const duplicate = !!(row && (row.exists_flag === 1 || row.exists_flag === '1'));
  out.push({ json: { ...rec, duplicate } });
}
return out;

