// Parse the model's JSON content; fall back to neutral on any error.
const allowed = new Set(['positive', 'neutral', 'negative']);
const upstream = $('Is Duplicate?').all();
const outs = [];
for (let i = 0; i < upstream.length; i++) {
  const base = upstream[i].json;
  if (base.duplicate) continue; // defensive — duplicates don't reach here
  const resp = $input.all()[i] && $input.all()[i].json;
  let sentiment = 'neutral';
  let sentiment_score = 0.5;
  try {
    const content = resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
    if (content) {
      const parsed = JSON.parse(content);
      if (allowed.has(String(parsed.sentiment).toLowerCase())) sentiment = String(parsed.sentiment).toLowerCase();
      if (typeof parsed.sentiment_score === 'number') {
        sentiment_score = Math.max(0, Math.min(1, parsed.sentiment_score));
      }
    }
  } catch (_) { /* keep neutral default */ }
  outs.push({ json: { ...base, sentiment, sentiment_score } });
}
return outs;

// Attach inserted=true/false flag based on INSERT ... ON CONFLICT output.
const upstream = $('Attach Sentiment').all();
const dbRows = $input.all();
const out = [];
for (let i = 0; i < upstream.length; i++) {
  const base = upstream[i].json;
  const row = dbRows[i] && dbRows[i].json;
  const inserted = !!(row && row.id);
  out.push({ json: { ...base, inserted, row_id: row && row.id ? row.id : null } });
}
return out;

// Aggregate counters across every record that came through.
// Pulls from multiple upstream nodes so duplicates are also counted.
const dupNode = $('Attach Duplicate Flag').all();
const insertedNode = $('Attach Insert Flag').all();

const total_reviews_fetched = dupNode.length;
const total_duplicates_skipped = dupNode.filter(i => i.json.duplicate).length;
const total_inserted = insertedNode.filter(i => i.json.inserted).length;
const total_alerts = insertedNode.filter(i => i.json.inserted && i.json.sentiment === 'negative' && (i.json.rating != null && i.json.rating <= 2)).length;
const total_errors = Math.max(0, total_reviews_fetched - total_duplicates_skipped - total_inserted);

const run_id = (dupNode[0] && dupNode[0].json.run_id) || null;
const run_started_at = (dupNode[0] && dupNode[0].json.run_started_at) || null;
const run_finished_at = new Date().toISOString();

return [{
  json: {
    status: 'success',
    run_id,
    run_started_at,
    run_finished_at,
    total_reviews_fetched,
    total_inserted,
    total_duplicates_skipped,
    total_alerts,
    total_errors
  }
}];

// Final workflow output payload.
const summary = $('Aggregate Summary').first().json;
return [{ json: summary }];
